/// Emitted when a day's reports, workstreams, or summary changed, or a run
/// started or ended. Payload `{ day, running }`.
pub const DAY_INTELLIGENCE_EVENT: &str = "clovy://day-intelligence";
const TICK: StdDuration = StdDuration::from_secs(60);
const PRUNE_EVERY: StdDuration = StdDuration::from_secs(3600);

/// Tauri-managed state, present on every platform (commands answer
/// `unsupported` without activity capture).
pub struct DayIntelligenceState {
    embedder: Arc<LocalEmbedder>,
    notices: Mutex<NoticeQueue>,
    /// One pipeline run at a time (scheduler or "Generate").
    run: tokio::sync::Mutex<()>,
    running: AtomicBool,
    wake: tokio::sync::Notify,
    /// The capture failure already notified, so a repeated state is quiet.
    capture_failure: Mutex<Option<String>>,
}

fn lock<T>(mutex: &Mutex<T>) -> std::sync::MutexGuard<'_, T> {
    mutex
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct DayRequest {
    /// Local day, "YYYY-MM-DD".
    pub day: String,
}

/// Whether activity generation can run: an activity provider with JSON
/// schema support is chosen.
pub fn provider_state() -> ProviderState {
    let registry = crate::llm::registry();
    let provider = registry.usage.activity.clone();
    if matches!(provider, ProviderRef::None | ProviderRef::OpenRouter) {
        return ProviderState::Missing;
    }
    if registry
        .level_of(&provider)
        .is_some_and(crate::llm::StructuredOutputLevel::supports_json_schema)
    {
        ProviderState::Ready
    } else {
        ProviderState::Insufficient
    }
}

/// Registers the state and, where activity capture runs, the background
/// loop. Call after `activity::setup`.
pub fn setup(app: &mut tauri::App) {
    let models = crate::app_paths::app_data_dir(app.handle())
        .map(|dir| dir.join("models"))
        .unwrap_or_default();
    app.manage(DayIntelligenceState {
        embedder: Arc::new(LocalEmbedder::new(&models)),
        notices: Mutex::new(NoticeQueue::default()),
        run: tokio::sync::Mutex::new(()),
        running: AtomicBool::new(false),
        wake: tokio::sync::Notify::new(),
        capture_failure: Mutex::new(None),
    });
    if app.state::<ActivityState>().runtime().is_some() {
        start(app.handle().clone());
    }
}

fn emit(app: &AppHandle, day: &str, running: bool) {
    let _ = app.emit(
        DAY_INTELLIGENCE_EVENT,
        serde_json::json!({ "day": day, "running": running }),
    );
}

fn start(app: AppHandle) {
    tauri::async_runtime::spawn(async move {
        let mut last_prune: Option<Instant> = None;
        loop {
            tick(&app, &mut last_prune).await;
            let state = app.state::<DayIntelligenceState>();
            let until_notice = lock(&state.notices)
                .next_delivery()
                .and_then(|at| (at - Utc::now()).to_std().ok())
                .unwrap_or(TICK);
            tokio::select! {
                _ = tokio::time::sleep(until_notice.min(TICK)) => {}
                _ = state.wake.notified() => {}
            }
        }
    });
}

fn deliver_notices(
    app: &AppHandle,
    state: &DayIntelligenceState,
    settings: &crate::activity::settings::ActivitySettings,
) {
    let due = lock(&state.notices).take_due(Utc::now(), &SystemZone, &settings.notifications);
    let locale = crate::interface_locale::current();
    for notice in due {
        let (title, body, snooze_label) = notify::copy(&notice, locale);
        let result = crate::notifications::send_today_notification(
            app,
            &crate::notifications::TodayNotification {
                title,
                body,
                day: notice.day.clone(),
                kind: notice.kind.as_str().to_string(),
                snooze_label,
            },
        );
        if let Err(error) = result {
            tracing::warn!(%error, "activity notification failed");
        }
    }
}

fn raise(app: &AppHandle, kind: NoticeKind, day: String, detail: Option<String>) {
    let Some(state) = app.try_state::<DayIntelligenceState>() else {
        return;
    };
    let Some(runtime) = app
        .state::<ActivityState>()
        .runtime()
        .map(|runtime| runtime.shared().settings())
    else {
        return;
    };
    lock(&state.notices).raise(
        kind,
        day,
        detail,
        Utc::now(),
        &SystemZone,
        &runtime.notifications,
    );
    state.wake.notify_one();
}

/// Called with every capture state change: an error or a lost key raises a
/// failure notification once per distinct failure.
pub fn on_capture_state(app: &AppHandle, capture: &CaptureState) {
    let Some(state) = app.try_state::<DayIntelligenceState>() else {
        return;
    };
    let failure = match capture {
        CaptureState::KeyMissing => {
            Some("The activity database key is missing from the Keychain.".to_string())
        }
        CaptureState::Error { message } => Some(message.clone()),
        _ => None,
    };
    let changed = {
        let mut last = lock(&state.capture_failure);
        let changed = failure.is_some() && *last != failure;
        last.clone_from(&failure);
        changed
    };
    if changed {
        let day = day_key(local_day(&SystemZone, Utc::now()));
        raise(app, NoticeKind::CaptureFailed, day, failure);
    }
}

/// The notification's "Snooze 1h" button.
pub fn snooze_notice(app: &AppHandle, kind: &str, day: &str) {
    let (Some(state), Some(kind)) = (
        app.try_state::<DayIntelligenceState>(),
        NoticeKind::parse(kind),
    ) else {
        return;
    };
    lock(&state.notices).snooze(kind, day.to_string(), None, Utc::now());
    state.wake.notify_one();
}

async fn tick(app: &AppHandle, last_prune: &mut Option<Instant>) {
    let state = app.state::<DayIntelligenceState>();
    let activity = app.state::<ActivityState>();
    let Some(runtime) = activity.runtime() else {
        return;
    };
    let settings = runtime.shared().settings();
    deliver_notices(app, &state, &settings);
    let Some(store) = runtime.shared().store() else {
        return;
    };
    let zone = SystemZone;
    let now = Utc::now();
    // Reports and summaries follow the retention period whenever the
    // database is open, also with capture off.
    if last_prune.map_or(true, |at| at.elapsed() >= PRUNE_EVERY) {
        *last_prune = Some(Instant::now());
        if let Err(error) = pipeline::prune(&store, &settings, &zone, now).await {
            tracing::warn!(%error, "day intelligence retention failed");
        }
    }
    if !settings.enabled {
        return;
    }
    run_scheduled_generation(
        provider_state(),
        tick_generation(app, &state, &store, &settings, now),
    )
    .await;
}

/// The scheduler must not poll generation work without a ready provider.
/// Its state is also the provider state exposed by the day view.
async fn run_scheduled_generation(
    provider: ProviderState,
    work: impl std::future::Future<Output = ()>,
) -> ProviderState {
    if provider == ProviderState::Ready {
        work.await;
    }
    provider
}

async fn tick_generation(
    app: &AppHandle,
    state: &DayIntelligenceState,
    store: &ActivityStore,
    settings: &crate::activity::settings::ActivitySettings,
    now: chrono::DateTime<Utc>,
) {
    let zone = SystemZone;
    // Text is written in the interface language: before the saved file or
    // the webview says which, nothing is generated (the next tick retries).
    let Some(locale) = crate::interface_locale::known() else {
        return;
    };
    if state.embedder.status() == EmbedderStatus::Absent {
        let embedder = Arc::clone(&state.embedder);
        tauri::async_runtime::spawn(async move { embedder.ensure_ready().await });
    }
    let Ok(_guard) = state.run.try_lock() else {
        return;
    };
    let today = local_day(&zone, now);
    let sources = AppSources {
        app: app.clone(),
        profile: None,
    };
    let deps = Deps {
        store,
        settings,
        generator: &ActivityProvider,
        embedder: state.embedder.as_ref(),
        sources: &sources,
        zone: &zone,
        locale,
        now,
    };
    // Today's reports and summary in another language are written again.
    match pipeline::relocalize_day(&deps, today).await {
        Ok(true) => emit(app, &day_key(today), false),
        Ok(false) => {}
        Err(error) => tracing::warn!(%error, "day intelligence relocalization failed"),
    }
    let yesterday = today - Duration::days(1);
    for day in [yesterday, today] {
        match pipeline::catch_up_day(&deps, day, false).await {
            Ok(result) if result.reported + result.folded > 0 => emit(app, &day_key(day), false),
            Ok(_) => {}
            Err(error) => tracing::warn!(%error, "day intelligence catch-up failed"),
        }
    }
    // A summary a language change removed is written again as soon as its
    // reports are, not at the scheduled time; yesterday's too, which past
    // midnight its scheduled run would never write again.
    for (day, result) in pipeline::finish_pending_resummaries(&deps, today).await {
        match result {
            Ok(Some(pipeline::SummaryRun::Generated(_))) => emit(app, &day_key(day), false),
            Ok(_) => {}
            Err(error) => tracing::warn!(%error, "day summary in the new language failed"),
        }
    }
    let mut records = Vec::with_capacity(2);
    for day in [yesterday, today] {
        match db::run_record(store, &format!("auto:{}", day_key(day))).await {
            Ok(record) => records.push(record),
            Err(error) => {
                tracing::warn!(%error, "day summary run record unreadable");
                return;
            }
        }
    }
    let Some(day) = schedule::auto_summary_day(
        zone.local(now),
        &settings.day_summary.time,
        records[0].as_ref(),
        records[1].as_ref(),
        now,
    ) else {
        return;
    };
    let key = day_key(day);
    let started = || {
        state.running.store(true, Ordering::SeqCst);
        emit(app, &key, true);
    };
    let outcome = pipeline::run_scheduled_summary(&deps, day, &started).await;
    let generated = state.running.swap(false, Ordering::SeqCst);
    match outcome {
        Ok(ScheduledRun::Waiting(reason)) => {
            tracing::debug!(day = %key, %reason, "day summary waits for its inputs");
        }
        Ok(ScheduledRun::Generated(summary)) => {
            raise(
                app,
                NoticeKind::SummaryReady,
                key.clone(),
                Some(summary.headline),
            );
        }
        Ok(ScheduledRun::Empty) => {}
        Ok(ScheduledRun::Failed { message, first }) => {
            tracing::warn!(%message, "scheduled day summary failed");
            if first {
                raise(app, NoticeKind::SummaryFailed, key.clone(), Some(message));
            }
        }
        Err(error) => tracing::warn!(%error, "day summary run not recorded"),
    }
    if generated {
        emit(app, &key, false);
    }
}

fn parse_request_day(day: &str) -> Result<NaiveDate, AppError> {
    parse_day(day)
        .ok_or_else(|| AppError::new("day_intelligence_invalid_day", "`day` must be YYYY-MM-DD"))
}

fn empty_dto(
    availability: Availability,
    day: &str,
    state: &DayIntelligenceState,
    summary_time: String,
) -> DayIntelligenceDto {
    DayIntelligenceDto {
        availability,
        day: day.to_string(),
        provider: provider_state(),
        embedder: state.embedder.status(),
        running: state.running.load(Ordering::SeqCst),
        summary_time,
        summary: None,
        workstreams: Vec::new(),
        hour_reports: Vec::new(),
        panels: DayPanelsDto::default(),
    }
}

async fn read_dto(
    app: &AppHandle,
    state: &DayIntelligenceState,
    store: &ActivityStore,
    settings: &crate::activity::settings::ActivitySettings,
    day: NaiveDate,
    profile: Option<&str>,
) -> Result<DayIntelligenceDto, AppError> {
    let sources = AppSources {
        app: app.clone(),
        profile: profile.map(str::to_owned),
    };
    let context = ReadContext {
        store,
        settings,
        sources: &sources,
        zone: &SystemZone,
        now: Utc::now(),
    };
    let (summary, workstreams, hour_reports, panels) = pipeline::day_view(&context, day)
        .await
        .map_err(|error| AppError::new("day_intelligence_read_failed", error.to_string()))?;
    Ok(DayIntelligenceDto {
        availability: Availability::Ready,
        day: day_key(day),
        provider: provider_state(),
        embedder: state.embedder.status(),
        running: state.running.load(Ordering::SeqCst),
        summary_time: settings.day_summary.time.clone(),
        summary,
        workstreams,
        hour_reports,
        panels,
    })
}

/// The "Today" view's day intelligence: summary, workstreams, hour reports,
/// and panels computed from the data now.
#[tauri::command]
pub async fn day_intelligence_day(
    app: AppHandle,
    state: State<'_, DayIntelligenceState>,
    activity: State<'_, ActivityState>,
    request: DayRequest,
) -> Result<DayIntelligenceDto, AppError> {
    let day = parse_request_day(&request.day)?;
    let Some(runtime) = activity.runtime() else {
        return Ok(empty_dto(
            Availability::Unsupported,
            &request.day,
            &state,
            String::new(),
        ));
    };
    let settings = runtime.shared().settings();
    let store = match timeline::store_access(runtime).await {
        StoreAccess::Open(store) => store,
        StoreAccess::Empty => {
            return Ok(empty_dto(
                Availability::Ready,
                &request.day,
                &state,
                settings.day_summary.time,
            ))
        }
        StoreAccess::Unavailable(availability, _) => {
            return Ok(empty_dto(
                availability,
                &request.day,
                &state,
                settings.day_summary.time,
            ))
        }
    };
    read_dto(&app, &state, &store, &settings, day, None).await
}

/// Typed on-demand port; preserves the UI service's provider, empty-day,
/// closed-store and pending-hour errors and its publication events.
pub(crate) async fn tool_generate(
    app: &AppHandle,
    day: String,
    binding: &crate::mcp_server::turns::TurnBinding,
    profile: &str,
    dispatched: &AtomicBool,
) -> Result<DayIntelligenceDto, AppError> {
    generate_day(
        app.clone(),
        app.state::<DayIntelligenceState>(),
        app.state::<ActivityState>(),
        DayRequest { day },
        Some((binding, profile, dispatched)),
    )
    .await
}

struct TrackedActivityProvider<'a> {
    dispatched: Option<&'a AtomicBool>,
}
impl pipeline::Generator for TrackedActivityProvider<'_> {
    fn generate(
        &self,
        request: crate::llm::GenerateRequest,
    ) -> futures_util::future::BoxFuture<'_, Result<crate::llm::GenerateOutput, crate::llm::LlmError>>
    {
        Box::pin(async move {
            if let Some(dispatched) = self.dispatched {
                dispatched.store(true, Ordering::SeqCst);
            }
            pipeline::Generator::generate(&ActivityProvider, request).await
        })
    }
}

struct OnDemandPublication<'a> {
    app: AppHandle,
    day: String,
    running: &'a AtomicBool,
}
impl Drop for OnDemandPublication<'_> {
    fn drop(&mut self) {
        self.running.store(false, Ordering::SeqCst);
        emit(&self.app, &self.day, false);
    }
}

/// "Generate summary": reports the day's pending hours (retrying failed ones
/// now) and writes the summary in the interface language.
#[tauri::command]
pub async fn day_intelligence_generate(
    app: AppHandle,
    state: State<'_, DayIntelligenceState>,
    activity: State<'_, ActivityState>,
    request: DayRequest,
) -> Result<DayIntelligenceDto, AppError> {
    generate_day(app, state, activity, request, None).await
}

async fn generate_day(
    app: AppHandle,
    state: State<'_, DayIntelligenceState>,
    activity: State<'_, ActivityState>,
    request: DayRequest,
    authorization: Option<(&crate::mcp_server::turns::TurnBinding, &str, &AtomicBool)>,
) -> Result<DayIntelligenceDto, AppError> {
    let day = parse_request_day(&request.day)?;
    match provider_state() {
        ProviderState::Ready => {}
        ProviderState::Missing => return Err(LlmError::ActivityProviderMissing.into()),
        ProviderState::Insufficient => return Err(LlmError::StructuredOutputInsufficient.into()),
    }
    let runtime = activity.runtime().ok_or_else(|| {
        AppError::new(
            "activity_unsupported",
            "Activity capture is available on macOS only.",
        )
    })?;
    let settings = runtime.shared().settings();
    let StoreAccess::Open(store) = timeline::store_access(runtime).await else {
        return Err(AppError::new(
            "activity_database_closed",
            "The activity database is not open. Turn capture on first.",
        ));
    };
    if state.embedder.status() == EmbedderStatus::Absent {
        let embedder = Arc::clone(&state.embedder);
        tauri::async_runtime::spawn(async move { embedder.ensure_ready().await });
    }
    let _guard = state.run.lock().await;
    let repos = if let Some((binding, profile, _)) = authorization {
        let repos = crate::commands::repositories(&app).await?;
        crate::mcp_server::tools::revalidate_binding(Some(&app), &repos.pool, binding, profile)
            .await?;
        Some(repos)
    } else {
        None
    };
    state.running.store(true, Ordering::SeqCst);
    emit(&app, &request.day, true);
    let publication = OnDemandPublication {
        app: app.clone(),
        day: request.day.clone(),
        running: &state.running,
    };
    timeline::refresh_before_read(&app, &store).await;
    if let (Some((binding, profile, _)), Some(repos)) = (authorization, repos.as_ref()) {
        crate::mcp_server::tools::revalidate_binding(Some(&app), &repos.pool, binding, profile)
            .await?;
    }
    let sources = AppSources {
        app: app.clone(),
        profile: authorization.map(|(_, profile, _)| profile.to_owned()),
    };
    let zone = SystemZone;
    let provider = TrackedActivityProvider {
        dispatched: authorization.map(|(_, _, dispatched)| dispatched),
    };
    let deps = Deps {
        store: &store,
        settings: &settings,
        generator: &provider,
        embedder: state.embedder.as_ref(),
        sources: &sources,
        zone: &zone,
        locale: crate::interface_locale::current(),
        now: Utc::now(),
    };
    let result = match pipeline::summarize_on_demand(&deps, day).await {
        Ok(SummaryRun::Generated(_)) => Ok(()),
        Ok(SummaryRun::Empty) => Err(AppError::new(
            "day_summary_no_activity",
            "There is no activity to summarize for this day yet.",
        )),
        Ok(SummaryRun::Incomplete(reason)) => Err(AppError::new(
            "day_summary_incomplete",
            format!("The summary was not written because part of the day is not ready ({reason}). Try again in a few minutes."),
        )),
        Err(pipeline::PipelineError::Llm(error)) => Err(error.0.into()),
        Err(error) => Err(AppError::new("day_intelligence_failed", error.to_string())),
    };
    drop(publication);
    result?;
    read_dto(
        &app,
        &state,
        &store,
        &settings,
        day,
        authorization.map(|(_, profile, _)| profile),
    )
    .await
}

#[cfg(test)]
mod scheduler_provider_tests {
    use super::test_support as fixture;
    use super::*;
    use serde_json::json;

    #[tokio::test]
    async fn scheduled_summary_without_provider_stays_disabled_and_makes_no_call() {
        let _guard = crate::providers::GLOBAL_SETTINGS_TEST_LOCK.lock().await;
        let mut provider_settings = crate::providers::default_settings_for_tests();
        provider_settings.llm_usage.activity = ProviderRef::None;
        crate::providers::replace_current_settings_for_tests(provider_settings);
        let (_directory, store) = fixture::store().await;
        let mut settings = fixture::settings();
        settings.day_summary.time = "18:00".into();
        let zone = fixture::zone();
        let now = fixture::local(18, 5);
        let day = fixture::day();
        fixture::build_timeline(&store, now).await;
        let sources = fixture::sources();
        *lock(&sources.ingestion_scanned_at) = Some(now);
        let generator = fixture::FakeProvider::new(|request| {
            Ok(match fixture::kind(request) {
                "hour" => {
                    json!({"summary":"Synthetic work", "activities":[{"description":"Synthetic work", "minutes":1}]})
                }
                "fold" => json!({"placements":[]}),
                _ => {
                    json!({"headline":"Synthetic day", "narrative":"A synthetic meeting happened.", "insights":[], "standup":{"done":["Synthetic meeting"],"in_progress":[],"blockers":[]}})
                }
            })
        });
        let deps = fixture::deps(
            &store,
            &settings,
            &generator,
            &sources,
            &zone,
            crate::interface_locale::UiLocale::En,
            now,
        );
        let yesterday_done = schedule::RunRecord {
            attempts: 1,
            outcome: schedule::RunOutcome::Ok,
            next_attempt_at: None,
        };
        assert_eq!(
            schedule::auto_summary_day(
                zone.local(now),
                &settings.day_summary.time,
                Some(&yesterday_done),
                None,
                now
            ),
            Some(day)
        );
        let started = AtomicBool::new(false);
        let scheduled = async {
            pipeline::catch_up_day(&deps, day, false).await.unwrap();
            pipeline::run_scheduled_summary(&deps, day, &|| {
                started.store(true, Ordering::SeqCst);
            })
            .await
            .unwrap();
        };
        assert_eq!(
            run_scheduled_generation(provider_state(), scheduled).await,
            ProviderState::Missing
        );
        assert!(generator.calls().is_empty());
        assert!(!started.load(Ordering::SeqCst));
        assert!(db::summary_of_day(&store, &day_key(day))
            .await
            .unwrap()
            .is_none());
        assert!(db::run_record(&store, &format!("auto:{}", day_key(day)))
            .await
            .unwrap()
            .is_none());

        // The actual day-view DTO reports the missing provider and idle state;
        // no embedder is fetched or initialized by this skipped generation.
        let models = tempfile::tempdir().unwrap();
        let state = DayIntelligenceState {
            embedder: Arc::new(LocalEmbedder::new(models.path())),
            notices: Mutex::new(NoticeQueue::default()),
            run: tokio::sync::Mutex::new(()),
            running: AtomicBool::new(false),
            wake: tokio::sync::Notify::new(),
            capture_failure: Mutex::new(None),
        };
        let dto = serde_json::to_value(empty_dto(
            Availability::Ready,
            &day_key(day),
            &state,
            settings.day_summary.time.clone(),
        ))
        .unwrap();
        assert_eq!(dto["provider"], "missing");
        assert_eq!(dto["running"], false);
        assert!(dto["summary"].is_null());
        assert_eq!(state.embedder.status(), EmbedderStatus::Absent);

        // Positive control: the same due work and fixtures really generate
        // through the scheduler boundary when a provider is ready.
        run_scheduled_generation(ProviderState::Ready, async {
            pipeline::catch_up_day(&deps, day, false).await.unwrap();
            assert!(matches!(
                pipeline::run_scheduled_summary(&deps, day, &|| {
                    started.store(true, Ordering::SeqCst);
                })
                .await
                .unwrap(),
                ScheduledRun::Generated(_)
            ));
        })
        .await;
        assert!(started.load(Ordering::SeqCst));
        assert!(!generator.calls().is_empty());
        assert!(db::summary_of_day(&store, &day_key(day))
            .await
            .unwrap()
            .is_some());
        crate::providers::replace_current_settings_for_tests(
            crate::providers::default_settings_for_tests(),
        );
    }
}
